Hub.StabSilent = function(self, targetPlr, knife)
	local ch = targetPlr.Character;
	local root = self:GetRoot(ch);
	local hum = ch and ch:FindFirstChildOfClass("Humanoid");
	if not (root and hum and (hum.Health > 0) and knife) then
		return;
	end
	for _, o in ipairs(knife:GetDescendants()) do
		if o:IsA("RemoteEvent") then
			pcall(function()
				o:FireServer(root, root.Position);
			end);
		elseif o:IsA("RemoteFunction") then
			pcall(function()
				o:InvokeServer(root, root.Position);
			end);
		end
	end
	if firetouchinterest then
		local handle = knife:FindFirstChild("Handle") or knife:FindFirstChildWhichIsA("BasePart");
		if handle then
			pcall(function()
				firetouchinterest(handle, root, 0);
				firetouchinterest(handle, root, 1);
			end);
		end
	end
end;
Hub.ExecuteKillAll = function(self)
