	clone.Name = "PreviewRig";
	local cframeOrigin = char:GetPivot();
	for _, item in ipairs(char:GetChildren()) do
		if (item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic") or item:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\22\194\93\196\24\59\193\86\207\40", "\91\84\173\57\189")) or item:IsA("CharacterMesh")) then
			pcall(function()
