Hub.FindTradeGui = function(self)
	local lp = self.Services.Players.LocalPlayer;
	local pg = lp and lp:FindFirstChild("PlayerGui");
	if not pg then
		return nil;
	end
	local mainGui = pg:FindFirstChild("MainGUI");
	local tradeGui = pg:FindFirstChild("TradeGUI") or (mainGui and mainGui:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\72\163\167\119\200", "\173\28\209\198\19"), true));
	if not tradeGui then
		return nil;
	end
	local isOpen = false;
	if tradeGui:IsA("ScreenGui") then
		isOpen = tradeGui.Enabled;
	elseif tradeGui:IsA("GuiObject") then
		isOpen = tradeGui.Visible;
		local cur = tradeGui.Parent;
		while cur and cur:IsA("GuiObject") do
			if not cur.Visible then
				isOpen = false;
				break;
			end
			cur = cur.Parent;
		end
	end
	if not isOpen then
		return nil;
	end
	return tradeGui;
end;
