Hub.ProcessInventoryWindow = function(self, inv)
	if (not inv or not inv:IsA("GuiObject") or not inv.Visible) then
		local old = inv and inv:FindFirstChild("MM2TotalValueHeader", true);
		if old then
			old.Visible = false;
		end
