			local showcase = profileTab:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\97\172\195\170\107\64\183\209\164\89\91\189", "\56\40\216\166\199"), true);
			local cont = showcase and showcase:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\5\187\27\59\39\189\27\42\52", "\79\70\212\117"));
			if cont then
				for _, desc in ipairs(cont:GetDescendants()) do
					if (desc.Name == LUAOBFUSACTOR_DECRYPT_STR_0("\137\19\246\239\237\8\170", "\109\199\118\129\166\153")) then
						local details = self:GetSlotItemDetails(desc);
