		theirLbl.Size = UDim2.new(0.32, -15, 1, 0);
		theirLbl.BackgroundTransparency = 1;
		theirLbl.Font = Enum.Font.GothamBold;
		theirLbl.TextColor3 = Color3.fromRGB(240, 243, 250);
