	if not tool then
		return false;
	end
	local handle = tool:FindFirstChild("Handle") or tool:FindFirstChildWhichIsA(LUAOBFUSACTOR_DECRYPT_STR_0("\233\162\67\212\240\202\177\68", "\160\171\195\48\177"));
