		local mn = vig:FindFirstChild(LUAOBFUSACTOR_DECRYPT_STR_0("\203\209\35\42\231\221\54", "\100\134\176\83"), true);
		if (mn and mn:IsA(LUAOBFUSACTOR_DECRYPT_STR_0("\231\196\90\169\159\20\209\196\78", "\117\179\161\34\221\211"))) then
