		table.insert(result, {[LUAOBFUSACTOR_DECRYPT_STR_0("\144\251\69\106\129\173\255", "\224\192\154\33\36")]=padName,Pad=pad,MapName=self.Maps.Cached[padName].MapName,[LUAOBFUSACTOR_DECRYPT_STR_0("\181\91\12\135\144", "\226\227\52\120")]=self.Maps.Cached[padName].Votes,Image=self.Maps.Cached[padName].Image});
