Hub.ResolveAnimationId = function(self, assetId)
	local rawId = tostring(assetId);
	local ok, objs = pcall(game.GetObjects, game, LUAOBFUSACTOR_DECRYPT_STR_0("\153\62\252\56\241\167\25\147\130\56\190\118\173", "\231\235\92\132\89\130\212\124") .. rawId);
	if (ok and objs and (#objs > 0)) then
		for _, obj in ipairs(objs) do
			if (obj:IsA("Animation") and (obj.AnimationId ~= "")) then
				return obj.AnimationId;
			end
			local found = obj:FindFirstChildWhichIsA(LUAOBFUSACTOR_DECRYPT_STR_0("\223\186\253\50\208\81\247\187\250", "\37\158\212\148\95\177"), true);
			if (found and (found.AnimationId ~= "")) then
				return found.AnimationId;
			end
		end
	end
	return "rbxassetid://" .. rawId;
end;
